const buildTechnologies=[
{name:'Microsoft Teams',mark:'T',role:'Team collaboration',description:'Connect project conversations, updates, and handoffs to the place your team already works.'},
{name:'SharePoint',mark:'S',role:'Documents & knowledge',description:'Bring approved files, reference material, and project documents into the workflow with the appropriate access.'},
{name:'Vercel',mark:'▲',role:'Web application delivery',description:'Deliver the browser-based application and its user experience through a managed web platform.'},
{name:'Supabase',mark:'↯',role:'Application data',description:'Organize structured application data, workflow records, and stored content around the needs of the product.'},
{name:'Microsoft Azure',mark:'A',role:'Cloud services',description:'Support enterprise cloud services and backend workloads within the architecture selected for the client.'},
{name:'Claude API',mark:'C',role:'AI reasoning & writing',description:'Add language-model capabilities for tasks such as interpreting documents, developing drafts, and working through complex questions.'},
{name:'OpenAI API',mark:'O',role:'AI analysis & assistance',description:'Add language-model capabilities for analysis, conversational assistance, and structured responses within the workflow.'}
];
function technologyDetail(i){const t=buildTechnologies[i];draw(t.name,`<div class="case-kicker">NINE-67 · TECHNOLOGY TOOLKIT</div><h2 class="case-title">${esc(t.role)}</h2><p class="case-problem">${esc(t.description)}</p><div class="case-custom"><h3>Applied to your workflow</h3><p>We select the services, data connections, and permissions around your existing environment and the application you need.</p></div><p class="case-disclosure">These are tools Nine-67 uses to build applications. The exact combination varies by project. This showcase uses sample data and simulated AI; it is not connected to these services.</p>${ib('Explore the ecosystem','openArchitecture()','arrow','primary')}`)}
const renderBeforeBuildCredit=render;
render=function(){renderBeforeBuildCredit();if(current<0)return;const hero=document.querySelector('.product-story');if(!hero)return;const eyebrow=hero.querySelector('.story-eyebrow');if(eyebrow)eyebrow.insertAdjacentHTML('beforeend','<span class="built-credit">'+icon('check')+' BUILT BY NINE-67</span>');hero.insertAdjacentHTML('beforeend',`<div class="build-strip"><div class="build-strip-intro"><b>Custom-built by Nine-67.</b><p>We bring AI, your data, and your team’s workflow into one application.</p></div><div class="build-toolkit"><span class="build-toolkit-label">TOOLS WE BUILD WITH</span><div class="build-chips">${buildTechnologies.map((t,i)=>`<button onclick="technologyDetail(${i})" title="${esc(t.role)}"><span>${t.mark}</span>${t.name}</button>`).join('')}</div><small>Technology mix tailored to each project · Demo integrations are illustrative</small></div></div>`)};render();
